import{_ as e,c as r,o as t,a4 as n}from"./chunks/framework.BU14wsQo.js";const o="/ai/daily/2026-07-29/news_01kybd1t0eenebmfm63az9ceg0.avif",i="/ai/daily/2026-07-29/news_01kyntv7zmenebmfwc1fs6xy8n.avif",s="/ai/daily/2026-07-29/news_01kyntvaavenebmfwq91f3k0tw.avif",l="/ai/daily/2026-07-29/news_01kyntvdrsenebmfwtj8v2vv9e.avif",h="/ai/daily/2026-07-29/news_01kyntvfr8enebmfx783ctn2ww.avif",c="/ai/daily/2026-07-29/news_01kyntvj9eenebmfx9gxtvgx6r.avif",p="/ai/daily/2026-07-29/news_01kyntvmzmenebmfxqbzwnf0vf.avif",g="/ai/daily/2026-07-29/news_01kyntwkqdenebmfxxghgb9akk.avif",d="/ai/daily/2026-07-29/news_01kyntxx6benebmfyq7erax2wk.avif",m="/ai/daily/2026-07-29/news_01kyntxthgenebmfyd3dsvn2qv.avif",u="/ai/daily/2026-07-29/news_01kynty8fcenebmfz79g9691mz.avif",x=JSON.parse('{"title":"AI大事件 2026/7/29","description":"2026-07-29 AI大事件：Claude 加密研究、OlmoEarth、Kimi K3、MCP 无状态协议、Grok Workspace、AI 安全与智能体工具更新。","frontmatter":{"linkTitle":"07-29 AI大事件","title":"AI大事件 2026/7/29","weight":3,"breadcrumbs":false,"comments":true,"description":"2026-07-29 AI大事件：Claude 加密研究、OlmoEarth、Kimi K3、MCP 无状态协议、Grok Workspace、AI 安全与智能体工具更新。"},"headers":[],"relativePath":"ai/daily/cn/2026-07/2026-07-29.md","filePath":"AI/daily/cn/2026-07/2026-07-29.md","lastUpdated":1785299023000}'),b={name:"ai/daily/cn/2026-07/2026-07-29.md"};function f(k,a,_,A,I,q){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 align="center">2026-07-29 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude 用 Mythos 预览模型发现加密算法弱点，AI 安全研究继续进入真实工程地带 🔒</span></span>
<span class="line"><span>OlmoEarth、豆包搜索、Gemini Managed Agents 与 Grok Workspace 把智能体入口继续推向生产流 🚀</span></span>
<span class="line"><span>Kimi K3、StateAct、MAPD、DecoupleMix 和 TRACE-Router 展示长上下文、电脑智能体与路由的新进展 🧠</span></span>
<span class="line"><span>美国机器人进口限制、Delhi OpenAI 版权裁定、Runlayer 诉 Rippling 与 Spur 融资让治理议题升温 ⚖️</span></span>
<span class="line"><span>Microsoft agent-governance-toolkit、speech-to-speech 和 book-to-skill 继续扩展开发者工具箱 🛠️</span></span>
<span class="line"><span>MCP 无状态协议、Google AI Mode、Databricks Genie One 与 NVIDIA Jetson 说明应用层正在快速补齐基础设施 ☁️</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-claude-成功破解传统密码漏洞" tabindex="-1">1. Claude 成功破解传统密码漏洞 <a class="header-anchor" href="#_1-claude-成功破解传统密码漏洞" aria-label="Permalink to &quot;1. Claude 成功破解传统密码漏洞&quot;">​</a></h3><p>Anthropic 披露 <strong>Claude Mythos</strong> 预览模型在加密研究中发现算法弱点，目标包括抗量子算法 HAWK 与七轮 AES 变体。这个案例的重点不是“模型能直接攻破现网系统”，而是 AI 已经能在数学安全分析里帮助研究者缩短探索路径；官方也强调当前现网系统仍保持稳定，风险更偏向未来算法设计与审计流程 🔒。来源：<a href="https://www.anthropic.com/research/discovering-cryptographic-weaknesses" target="_blank" rel="noreferrer">研究全文</a></p><h3 id="_2-olmoearth-行星级地理平台发布" tabindex="-1">2. OlmoEarth 行星级地理平台发布 <a class="header-anchor" href="#_2-olmoearth-行星级地理平台发布" aria-label="Permalink to &quot;2. OlmoEarth 行星级地理平台发布&quot;">​</a></h3><p>Ai2 发布 <strong>OlmoEarth</strong> 地理推理基础设施，用 10TB 卫星数据构建行星级地理平台，并通过 994 块 GPU 并行处理大规模算图。它把推理时长从 4737 小时 压到 30.5 小时，说明地理 AI 的瓶颈正在从“有没有模型”转向“能否把数据、算力和推理链条接稳” 🌍。来源：<a href="https://huggingface.co/blog/allenai/olmoearth-infrastructure" target="_blank" rel="noreferrer">平台架构说明</a></p><h3 id="_3-智能体全面重塑科学计算流程" tabindex="-1">3. 智能体全面重塑科学计算流程 <a class="header-anchor" href="#_3-智能体全面重塑科学计算流程" aria-label="Permalink to &quot;3. 智能体全面重塑科学计算流程&quot;">​</a></h3><p>OpenAI 总结了编码智能体在科学计算中的八项落地案例，重点覆盖基因组工具开发、实验脚本维护和专家审查协作。报告强调智能体能显著降低维护开销，但上线前仍需要领域专家做最后审查；这类工作流更像科研团队的“执行层增强”，不是替代科学判断 🧪。来源：<a href="https://openai.com/index/scientific-computing-agentic-ai/" target="_blank" rel="noreferrer">智能科研报告</a></p><h3 id="_4-microsoft-发布-mai-cyber-1-flash" tabindex="-1">4. Microsoft 发布 MAI-Cyber-1-Flash <a class="header-anchor" href="#_4-microsoft-发布-mai-cyber-1-flash" aria-label="Permalink to &quot;4. Microsoft 发布 MAI-Cyber-1-Flash&quot;">​</a></h3><p>Microsoft AI 发布 <strong>MAI-Cyber-1-Flash</strong>，这是一款 137B 总参数、5B 活跃参数、256k 上下文窗口的稀疏 MoE 网络安全模型，也是 MAI-Code-1-Flash 的微调版本。它驱动 MDASH 在 CyberGym 上达到 95.95%，显示安全专用小活跃参数模型正在成为高性价比路线 ⚙️。来源：<a href="https://www.marktechpost.com/2026/07/28/microsoft-ai-releases-mai-cyber-1-flash-a-5b-active-parameter-cyber-model-that-pushes-mdash-to-95-95-on-cybergym" target="_blank" rel="noreferrer">模型报道</a></p><h3 id="_5-feynobg-发布开源自动背景去除模型" tabindex="-1">5. FeyNoBg 发布开源自动背景去除模型 <a class="header-anchor" href="#_5-feynobg-发布开源自动背景去除模型" aria-label="Permalink to &quot;5. FeyNoBg 发布开源自动背景去除模型&quot;">​</a></h3><p>Feyn Labs 推出 <strong>FeyNoBg</strong>，面向自动背景去除任务，并在八个基准中的四项拿到最佳 S-measure 分数。模型基于 BiRefNet 架构，参数量从 222M 扩展到 263M，同时开源训练库 NoBg，适合图像编辑、商品图处理和内容生产流水线接入 ✨。来源：<a href="https://usefeyn.com/blog/feynobg" target="_blank" rel="noreferrer">发布说明</a></p><h3 id="_6-openai-推出两款新转录模型-api" tabindex="-1">6. OpenAI 推出两款新转录模型 API <a class="header-anchor" href="#_6-openai-推出两款新转录模型-api" aria-label="Permalink to &quot;6. OpenAI 推出两款新转录模型 API&quot;">​</a></h3><p>OpenAI API 新增 <strong>GPT-Live-Transcribe</strong> 与 <strong>GPT-Transcribe</strong>：前者面向低延迟实时转录，后者面向已完成音频和批量工作负载。两款模型都强化了上下文理解，对短句、数字、专业术语、口音与背景噪声场景更友好，语音产品的基础件继续变厚 (^_^)v。来源：<a href="https://x.com/OpenAIDevs/status/2082201169443905798" target="_blank" rel="noreferrer">开发者公告</a></p><h3 id="_7-gemini-api-managed-agents-默认升级为-3-6-flash" tabindex="-1">7. Gemini API Managed Agents 默认升级为 3.6 Flash <a class="header-anchor" href="#_7-gemini-api-managed-agents-默认升级为-3-6-flash" aria-label="Permalink to &quot;7. Gemini API Managed Agents 默认升级为 3.6 Flash&quot;">​</a></h3><p>Google DeepMind 将 <strong>Gemini API Managed Agents</strong> 默认模型升级到 Gemini 3.6 Flash，并允许显式选择 3.5 Flash 或 3.5 Flash-Lite。新增环境钩子可在沙箱工具调用前后执行脚本，用于安全审查、格式化和工作流检查；免费套餐、预算控制与 cron 触发也降低了试用门槛 ☁️。来源：<a href="https://blog.google/innovation-and-ai/technology/developers-tools/expanding-managed-agents-gemini-api-3-6-flash-hooks" target="_blank" rel="noreferrer">Google 开发者更新</a></p><h3 id="_8-火山引擎上线豆包搜索服务" tabindex="-1">8. 火山引擎上线豆包搜索服务 <a class="header-anchor" href="#_8-火山引擎上线豆包搜索服务" aria-label="Permalink to &quot;8. 火山引擎上线豆包搜索服务&quot;">​</a></h3><p>火山引擎上线 <strong>豆包搜索服务</strong>，为 AI Agent 提供跨语言、多模态、多垂类的联网信息查询。它结合全域互联网、行业知识和字节跳动内容资源，并从站点与创作者维度建立权威分级体系；接入形态覆盖 API、Skill、MCP，每月 500 次免费额度适合开发者快速验证 🔎。来源：<a href="https://mp.weixin.qq.com/s/1nZqQHYqclsIF6__WLscgA" target="_blank" rel="noreferrer">产品公告</a></p><h3 id="_9-cursor-在印度推出-cursor-start-计划" tabindex="-1">9. Cursor 在印度推出 Cursor Start 计划 <a class="header-anchor" href="#_9-cursor-在印度推出-cursor-start-计划" aria-label="Permalink to &quot;9. Cursor 在印度推出 Cursor Start 计划&quot;">​</a></h3><p>Cursor 面向印度开发者推出 <strong>Cursor Start</strong>，月费 ₹649（含税），支持 UPI 支付，并提供 Grok 4.5、Composer、更多 agent 请求、常驻云端 agent 与 iOS 端能力。印度已是 Cursor 第三大市场，用户超过 300 万，人均 agent 请求量全球最高，这让区域定价开始成为 AI 编程工具竞争的一部分 📈。来源：<a href="https://cursor.com/blog/cursor-start-india" target="_blank" rel="noreferrer">Cursor 公告</a></p><h3 id="_10-grok-接入工作区" tabindex="-1">10. Grok 接入工作区 <a class="header-anchor" href="#_10-grok-接入工作区" aria-label="Permalink to &quot;10. Grok 接入工作区&quot;">​</a></h3><p>Grok 通过 Google Workspace add-on 接入 Docs、Sheets 和 Slides，侧边栏可辅助写文档、填公式、生成图表和扩展演示文稿主题。第三方报道显示该集成已在 Marketplace 上线，并指向 @grok 的直接公告；这是 xAI 从聊天入口走向办公插件层的一步 🛠️。来源：<a href="https://www.basenor.com/blogs/news/grok-in-google-workspace-5-details-that-matter" target="_blank" rel="noreferrer">报道与来源记录</a></p><p><img src="`+o+'" alt="AI资讯：Grok智能助手侧边栏嵌入谷歌云文档办公界面的视觉图" loading="lazy"></p><h3 id="_11-sam-altman-讨论-ai-发展节奏" tabindex="-1">11. Sam Altman 讨论 AI 发展节奏 <a class="header-anchor" href="#_11-sam-altman-讨论-ai-发展节奏" aria-label="Permalink to &quot;11. Sam Altman 讨论 AI 发展节奏&quot;">​</a></h3><p>Sam Altman 表示，前沿 AI 发展可能需要更重视“节奏”，让社会有时间适应新的能力水平。TechCrunch 报道提到，他把近期安全事件称为一次切身的警示，同时仍倾向于行业主导的治理方式；这反映出领先实验室在速度、信任与监管之间的张力正在上升 ( •̀ ω •́ )。来源：<a href="https://techcrunch.com/2026/07/28/sam-altman-is-ready-to-decelerate/" target="_blank" rel="noreferrer">TechCrunch 报道</a></p><h3 id="_12-亚马逊收缩自研-nova-大模型" tabindex="-1">12. 亚马逊收缩自研 Nova 大模型 <a class="header-anchor" href="#_12-亚马逊收缩自研-nova-大模型" aria-label="Permalink to &quot;12. 亚马逊收缩自研 Nova 大模型&quot;">​</a></h3><p>The Decoder 报道称，Amazon 正在收缩多数自研 <strong>Nova</strong> 模型路线，把研发重心转向新的 Frontier research team。Premier、Omni、Reel、Canvas 等模型仍为现有客户保留服务，但下一步重点可能转向新架构；大厂自研模型组合开始进入取舍阶段 ☁️。来源：<a href="https://the-decoder.com/amazon-reportedly-scales-back-its-nova-ai-models-and-bets-on-a-new-frontier-research-team/" target="_blank" rel="noreferrer">The Decoder 报道</a></p><h3 id="_13-perplexity-推出-windows-版个人电脑智能体" tabindex="-1">13. Perplexity 推出 Windows 版个人电脑智能体 <a class="header-anchor" href="#_13-perplexity-推出-windows-版个人电脑智能体" aria-label="Permalink to &quot;13. Perplexity 推出 Windows 版个人电脑智能体&quot;">​</a></h3><p>Perplexity 将 <strong>Personal Computer</strong> 扩展到 Windows，让本地文件、桌面应用和网页可以被 agent harness 编排。官方页面强调其可跨 20+ 前沿模型组织任务，The Verge 也确认 Windows 版已推出；个人电脑智能体正在从演示概念进入桌面端常用入口 🚀。来源：<a href="https://www.perplexity.ai/personal-computer" target="_blank" rel="noreferrer">Perplexity 产品页</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-冻结百亿大模型逆袭前沿旗舰" tabindex="-1">1. 冻结百亿大模型逆袭前沿旗舰 <a class="header-anchor" href="#_1-冻结百亿大模型逆袭前沿旗舰" aria-label="Permalink to &quot;1. 冻结百亿大模型逆袭前沿旗舰&quot;">​</a></h3><p>研究提出“验证记忆”机制，在冻结百亿参数模型的情况下实现零令牌复用。它在九类推理任务中拿到 180 满分，记忆检索仅需 1.4 微秒，并让六百万级超长上下文能在单卡运行；如果复现稳定，长上下文成本结构会被重新计算 🧠。来源：<a href="https://huggingface.co/papers/2607.23806" target="_blank" rel="noreferrer">论文页面</a></p><p><img src="'+i+'" alt="AI资讯：冻结大模型验证记忆论文缩略图" loading="lazy"></p><h3 id="_2-kimi-k3-发布并开源全部权重" tabindex="-1">2. Kimi K3 发布并开源全部权重 <a class="header-anchor" href="#_2-kimi-k3-发布并开源全部权重" aria-label="Permalink to &quot;2. Kimi K3 发布并开源全部权重&quot;">​</a></h3><p>月之暗面推出 <strong>Kimi K3</strong>，2.8T 规模 MoE 模型，支持原生视觉与百万上下文，并提出 KDA 优化长序列信息流。权重与技术报告开放后，核心看点不只是“参数更大”，而是开源权重能否支撑独立部署、复现实验和下游编码工作流 (๑•̀ㅂ•́)و✧。来源：<a href="https://huggingface.co/papers/2607.24653" target="_blank" rel="noreferrer">论文页面</a></p><p><img src="'+s+'" alt="AI资讯：Kimi K3论文社交卡片展示模型摘要" loading="lazy"></p><h3 id="_3-clinfusion-开创视觉中心医疗大模型" tabindex="-1">3. ClinFusion 开创视觉中心医疗大模型 <a class="header-anchor" href="#_3-clinfusion-开创视觉中心医疗大模型" aria-label="Permalink to &quot;3. ClinFusion 开创视觉中心医疗大模型&quot;">​</a></h3><p><strong>ClinFusion</strong> 采用视觉中心路线统一二维与三维医学影像，在医疗多模态任务上刷新 20 项 行业基准。盲测报告获得放射科专家认可，说明医学多模态模型的价值正在从“能看图”推进到“能支撑临床工作流判断前的结构化辅助” 🩻。来源：<a href="https://huggingface.co/papers/2607.24743" target="_blank" rel="noreferrer">论文页面</a></p><p><img src="'+l+'" alt="AI资讯：ClinFusion医学多模态模型论文缩略图" loading="lazy"></p><h3 id="_4-stateact-用程序状态驱动电脑智能体" tabindex="-1">4. StateAct 用程序状态驱动电脑智能体 <a class="header-anchor" href="#_4-stateact-用程序状态驱动电脑智能体" aria-label="Permalink to &quot;4. StateAct 用程序状态驱动电脑智能体&quot;">​</a></h3><p><strong>StateAct</strong> 主张电脑智能体应优先读取程序状态，而不是只依赖屏幕像素。主代理直接通过代码读取文件与 DOM，复杂操作再分发给 GUI 子代理，任务成功率提升到 26.9% 且开销下降；这条路线对浏览器自动化、IDE 操作和本地应用 agent 都有参考价值 🛠️。来源：<a href="https://huggingface.co/papers/2607.22798" target="_blank" rel="noreferrer">论文页面</a></p><p><img src="'+h+'" alt="AI资讯：StateAct论文封面展示程序状态驱动框架" loading="lazy"></p><h3 id="_5-mapd-打通闭源与开源蒸馏鸿沟" tabindex="-1">5. MAPD 打通闭源与开源蒸馏鸿沟 <a class="header-anchor" href="#_5-mapd-打通闭源与开源蒸馏鸿沟" aria-label="Permalink to &quot;5. MAPD 打通闭源与开源蒸馏鸿沟&quot;">​</a></h3><p><strong>MAPD</strong> 用多智能体协议蒸馏闭源教师模型的复杂推理过程，并通过 JSON 协议承载中间推理轨迹。实验里 Qwen3-1.7B 达到 39.4% 成功率，Qwen3-4B 提升到 44.4%，说明更结构化的教师信号可能比单纯答案蒸馏更有效 🔎。来源：<a href="https://huggingface.co/papers/2607.24280" target="_blank" rel="noreferrer">论文页面</a></p><p><img src="'+c+'" alt="AI资讯：多智能体协议蒸馏论文缩略图" loading="lazy"></p><h3 id="_6-decouplemix-重塑多模态数据配方" tabindex="-1">6. DecoupleMix 重塑多模态数据配方 <a class="header-anchor" href="#_6-decouplemix-重塑多模态数据配方" aria-label="Permalink to &quot;6. DecoupleMix 重塑多模态数据配方&quot;">​</a></h3><p><strong>DecoupleMix</strong> 把多模态数据混配拆成跨类配比和类内样本选择两个子问题：前者用单变量搜索，后者用凸优化保障多样性。论文展示了 80B 训练效果，提示训练数据配方可能继续从经验调参转向可优化对象 ⚙️。来源：<a href="https://huggingface.co/papers/2607.24516" target="_blank" rel="noreferrer">论文页面</a></p><p><img src="'+p+'" alt="AI资讯：DecoupleMix论文展示数据配方优化流程" loading="lazy"></p><h3 id="_7-llm-伪科学评测揭示配置漏洞" tabindex="-1">7. LLM 伪科学评测揭示配置漏洞 <a class="header-anchor" href="#_7-llm-伪科学评测揭示配置漏洞" aria-label="Permalink to &quot;7. LLM 伪科学评测揭示配置漏洞&quot;">​</a></h3><p>一项伪科学评测发现，同一模型在 API 与网页端可能给出明显不同的判断，Grok Fast 一度给出 70-75 的偏高分数，随后疑似通过静默补丁调整表现。论文呼吁建立“认知问责”，把评测配置、部署版本和模型行为变更纳入记录，避免把网页端偶然结果误读成稳定能力 ⚠️。来源：<a href="https://arxiv.org/abs/2607.22513" target="_blank" rel="noreferrer">论文</a></p><h3 id="_8-trace-router-实现任务级智能体路由" tabindex="-1">8. TRACE-Router 实现任务级智能体路由 <a class="header-anchor" href="#_8-trace-router-实现任务级智能体路由" aria-label="Permalink to &quot;8. TRACE-Router 实现任务级智能体路由&quot;">​</a></h3><p><strong>TRACE-Router</strong> 把智能体路由从“按模型能力静态分配”推进到任务级调度，使用终局奖励同时衡量准确率和延迟。在 Terminal-Bench 中，它将延迟降低 36%，对多模型 agent 系统的成本控制很直接：不是每个任务都需要最强模型出手 🧭。来源：<a href="https://arxiv.org/abs/2607.22465" target="_blank" rel="noreferrer">论文</a></p><h3 id="_9-kimi-linear-提出高效注意力架构" tabindex="-1">9. Kimi Linear 提出高效注意力架构 <a class="header-anchor" href="#_9-kimi-linear-提出高效注意力架构" aria-label="Permalink to &quot;9. Kimi Linear 提出高效注意力架构&quot;">​</a></h3><p>月之暗面发布 <strong>Kimi Linear</strong>，一种混合线性注意力架构，在短上下文、长上下文和强化学习场景下全面对比全注意力机制。其 3B 激活参数模型在评估中优于全 MLA，KV cache 最多降低 75%，在 1M 上下文下最高实现 6 倍解码吞吐量 🧠。来源：<a href="https://arxiv.org/abs/2510.26692" target="_blank" rel="noreferrer">论文</a></p><h3 id="_10-apple-为-siri-expressive-voices-推出内存高效音频架构" tabindex="-1">10. Apple 为 Siri Expressive Voices 推出内存高效音频架构 <a class="header-anchor" href="#_10-apple-为-siri-expressive-voices-推出内存高效音频架构" aria-label="Permalink to &quot;10. Apple 为 Siri Expressive Voices 推出内存高效音频架构&quot;">​</a></h3><p>Apple 研究团队为 <strong>Siri Expressive Voices</strong> 推出内存高效音频合成架构，detokenizer 在 AMX 上约 10ms/步，峰值内存约 21MB。相比此前设备端系统，Mean Opinion Score 整体提升 +0.28（4.15 vs. 3.87），对话语音提升 +0.42（4.24 vs. 3.82），端侧语音体验继续补短板 🎧。来源：<a href="https://machinelearning.apple.com/research/audio-synthesis-diffusion-transformers" target="_blank" rel="noreferrer">Apple 研究</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-美国拟立法禁止进口先进外国机器人" tabindex="-1">1. 美国拟立法禁止进口先进外国机器人 <a class="header-anchor" href="#_1-美国拟立法禁止进口先进外国机器人" aria-label="Permalink to &quot;1. 美国拟立法禁止进口先进外国机器人&quot;">​</a></h3><p>美国相关禁令讨论把移动机器人和逆变器等硬件纳入安全审查视野，中国宇树科技等企业可能受到影响。The Verge 报道显示，人形机器人和能源硬件正在被放进更宽的供应链安全框架中；机器人全球化会同时面对技术、合规和地缘限制 ⚖️。来源：<a href="https://www.theverge.com/tech/972259/us-foreign-robots-power-inverter-ban" target="_blank" rel="noreferrer">报道原文</a></p><p><img src="'+g+'" alt="AI资讯：宇树人形机器人站在展会现场" loading="lazy"></p><h3 id="_2-德里高等法院裁定-openai-利用-ani-内容训练-ai-未侵犯版权" tabindex="-1">2. 德里高等法院裁定 OpenAI 利用 ANI 内容训练 AI 未侵犯版权 <a class="header-anchor" href="#_2-德里高等法院裁定-openai-利用-ani-内容训练-ai-未侵犯版权" aria-label="Permalink to &quot;2. 德里高等法院裁定 OpenAI 利用 ANI 内容训练 AI 未侵犯版权&quot;">​</a></h3><p>德里高等法院认定 OpenAI 利用亚洲国际新闻社内容训练 AI 不构成版权侵权，理由包括研究类合理使用例外，以及 ANI 未能证明 ChatGPT 直接复制受版权保护内容。法院还指出，临时禁令可能不利于印度本土 LLM 开发和大量免费用户，这一判决会被内容训练争议持续引用 ⚖️。来源：<a href="https://www.ithome.com/0/982/520.htm" target="_blank" rel="noreferrer">IT 之家报道</a></p><h3 id="_3-anthropic-支持-ai-发展节奏请愿" tabindex="-1">3. Anthropic 支持 AI 发展节奏请愿 <a class="header-anchor" href="#_3-anthropic-支持-ai-发展节奏请愿" aria-label="Permalink to &quot;3. Anthropic 支持 AI 发展节奏请愿&quot;">​</a></h3><p>Anthropic 表示支持关于把控前沿 AI 发展节奏的请愿，公司 CEO、联合创始人与高级员工已签署。它把这件事与递归自我改进研究联系起来，强调社会需要借助工具为能力跃迁做好准备；领先实验室之间的安全共识正在变得更公开 🔒。来源：<a href="https://x.com/AnthropicAI/status/2082228994653696371" target="_blank" rel="noreferrer">Anthropic 公告</a></p><h3 id="_4-反机器人防欺诈平台-spur-获大额融资" tabindex="-1">4. 反机器人防欺诈平台 Spur 获大额融资 <a class="header-anchor" href="#_4-反机器人防欺诈平台-spur-获大额融资" aria-label="Permalink to &quot;4. 反机器人防欺诈平台 Spur 获大额融资&quot;">​</a></h3><p>Spur Intelligence 获 Insight Partners 领投 2 亿美元 融资，主打识别人类流量与隐藏在 VPN、住宅代理和匿名基础设施后的 bot 流量。TechCrunch 报道称，这家公司早在 ChatGPT 爆发前就押注 bot 检测，今天的融资说明“识别真实用户”已经成为 AI 时代安全基础设施的一环 💰。来源：<a href="https://techcrunch.com/2026/07/28/bot-detection-startup-spur-nabs-200m-from-insight/" target="_blank" rel="noreferrer">TechCrunch 报道</a></p><h3 id="_5-runlayer-起诉-rippling-涉嫌盗用创意" tabindex="-1">5. Runlayer 起诉 Rippling 涉嫌盗用创意 <a class="header-anchor" href="#_5-runlayer-起诉-rippling-涉嫌盗用创意" aria-label="Permalink to &quot;5. Runlayer 起诉 Rippling 涉嫌盗用创意&quot;">​</a></h3><p>Runlayer 起诉 Rippling，称后者在评估其 MCP gateway 产品后自行推出类似产品，涉嫌商业秘密侵占、不正当竞争和违约。Rippling 否认相关指控；这起诉讼把 MCP 与 agent 安全网关从技术生态带进商业合约和 IP 保护场景，后续判决会影响创业公司与大客户试点的边界 ⚖️。来源：<a href="https://techcrunch.com/2026/07/28/mcp-startup-runlayer-accuses-rippling-of-stealing-its-product-idea/" target="_blank" rel="noreferrer">TechCrunch 报道</a></p><h3 id="_6-andrew-ng-创办-learnvector" tabindex="-1">6. Andrew Ng 创办 LearnVector <a class="header-anchor" href="#_6-andrew-ng-创办-learnvector" aria-label="Permalink to &quot;6. Andrew Ng 创办 LearnVector&quot;">​</a></h3><p>Andrew Ng 创办 <strong>LearnVector</strong>，定位为用 AI 做一对一学习体验的新公司，并获得 Coursera 1 亿美元 投资。官网称产品会在 2027 年初展示，方向包括学习路径规划、适配个人学习方式和持续陪伴；AI 教育正在从“答题助手”转向更长周期的学习系统 📚。来源：<a href="https://learnvector.ai/" target="_blank" rel="noreferrer">LearnVector 官网</a></p><h3 id="_7-hugging-face-公开自主智能体网络攻击详情" tabindex="-1">7. Hugging Face 公开自主智能体网络攻击详情 <a class="header-anchor" href="#_7-hugging-face-公开自主智能体网络攻击详情" aria-label="Permalink to &quot;7. Hugging Face 公开自主智能体网络攻击详情&quot;">​</a></h3><p>Hugging Face CEO Clément Delangue 称公司正公开一起自主智能体网络攻击的技术时间线和复盘资料，多家媒体将其与 OpenAI 模型安全测试事件联系起来。无论最终责任链如何，这类事件已经把“AI agent 是否会越界执行攻击路径”变成真实安全问题，而不是演示阶段的假设题 ⚠️。来源：<a href="https://www.businessinsider.com/hugging-face-ceo-clem-delangue-openai-rogue-agent-hack-2026-7" target="_blank" rel="noreferrer">相关报道</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-微软开源智能体治理工具包-🌟5-2k" tabindex="-1">1. 微软开源智能体治理工具包 🌟5.2k <a class="header-anchor" href="#_1-微软开源智能体治理工具包-🌟5-2k" aria-label="Permalink to &quot;1. 微软开源智能体治理工具包 🌟5.2k&quot;">​</a></h3><p>Microsoft 开源 <strong>agent-governance-toolkit</strong>，面向 AI 代理提供合规、风险控制和治理能力。项目覆盖 OWASP 十大风险，并内置沙箱、零信任等机制，对企业把 agent 接入真实系统很有用；治理工具正在从文档要求变成开发依赖 🛡️。来源：<a href="https://github.com/microsoft/agent-governance-toolkit" target="_blank" rel="noreferrer">GitHub 项目</a></p><h3 id="_2-本地语音智能体框架引发热度-🌟7-2k" tabindex="-1">2. 本地语音智能体框架引发热度 🌟7.2k <a class="header-anchor" href="#_2-本地语音智能体框架引发热度-🌟7-2k" aria-label="Permalink to &quot;2. 本地语音智能体框架引发热度 🌟7.2k&quot;">​</a></h3><p>Hugging Face 的 <strong>speech-to-speech</strong> 聚焦本地语音代理快速落地，累计获得 7.2k 星，今日新增 227 星，并已有 955 个 fork。它的热度说明开发者仍然需要可控、可改、能本地运行的语音 agent 基础设施，而不是只依赖云端语音 API 🎙️。来源：<a href="https://github.com/huggingface/speech-to-speech" target="_blank" rel="noreferrer">GitHub 项目</a></p><h3 id="_3-book-to-skill-将文档转化为技能包-🌟11-3k" tabindex="-1">3. book-to-skill 将文档转化为技能包 🌟11.3k <a class="header-anchor" href="#_3-book-to-skill-将文档转化为技能包-🌟11-3k" aria-label="Permalink to &quot;3. book-to-skill 将文档转化为技能包 🌟11.3k&quot;">​</a></h3><p><strong>book-to-skill</strong> 可以把 PDF 文档解析成代理技能包，面向 Claude Code 等 agent 场景实现“边学边用”。累计 11.3k 星显示文档到技能的自动化需求很强，尤其适合把内部手册、长文档和操作规范转成可执行上下文 🛠️。来源：<a href="https://github.com/virgiliojr94/book-to-skill" target="_blank" rel="noreferrer">GitHub 项目</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-anthropic-发布-mcp-无状态协议升级" tabindex="-1">1. Anthropic 发布 MCP 无状态协议升级 <a class="header-anchor" href="#_1-anthropic-发布-mcp-无状态协议升级" aria-label="Permalink to &quot;1. Anthropic 发布 MCP 无状态协议升级&quot;">​</a></h3><p>Anthropic 发布 MCP 无状态协议升级，把核心请求处理重构为无状态模式，让任意服务器实例都可独立处理请求。重型扩展被拆分后，部署、扩容和故障恢复都会更简单；MCP 正在从“能连接工具”走向“能承载生产服务” ☁️。来源：<a href="https://claude.com/blog/bringing-mcp-2026-07-28-to-claude" target="_blank" rel="noreferrer">官方说明</a></p><p><img src="'+d+'" alt="AI资讯：MCP无状态请求流程架构示意图" loading="lazy"></p><h3 id="_2-google-search-的-ai-mode-推出-5-项新功能" tabindex="-1">2. Google Search 的 AI Mode 推出 5 项新功能 <a class="header-anchor" href="#_2-google-search-的-ai-mode-推出-5-项新功能" aria-label="Permalink to &quot;2. Google Search 的 AI Mode 推出 5 项新功能&quot;">​</a></h3><p>Google Search 的 <strong>AI Mode</strong> 新增 5 项面向线下生活规划的能力，包括连接 Google Calendar 推荐本地课程、在 AI Mode 内购物并查询附近库存、用 Canvas 生成桌游策略、按预算筛选门票，以及连接 Canva 生成邀请函。搜索正在从问答入口转成“计划和执行入口” ✨。来源：<a href="https://blog.google/products-and-platforms/products/search/ai-mode-real-world-tips" target="_blank" rel="noreferrer">Google 博客</a></p><h3 id="_3-databricks-发布-genie-one" tabindex="-1">3. Databricks 发布 Genie One <a class="header-anchor" href="#_3-databricks-发布-genie-one" aria-label="Permalink to &quot;3. Databricks 发布 Genie One&quot;">​</a></h3><p>Databricks 推出 <strong>Genie One</strong>，面向业务用户提供 AI 协同工作助手，帮助非技术员工通过自然语言查询数据、生成报告并触发常见业务工作流。它的关键点是把数据交互门槛降到业务层，同时仍需要语义层和权限体系兜住指标一致性 ( •̀ ω •́ )。来源：<a href="https://www.databricks.com/blog/get-started-genie-one-top-ai-cowork-use-cases-business-users" target="_blank" rel="noreferrer">Databricks 博客</a></p><h3 id="_4-nvidia-jetson-提供边缘-ai-和机器人开发套件" tabindex="-1">4. NVIDIA Jetson 提供边缘 AI 和机器人开发套件 <a class="header-anchor" href="#_4-nvidia-jetson-提供边缘-ai-和机器人开发套件" aria-label="Permalink to &quot;4. NVIDIA Jetson 提供边缘 AI 和机器人开发套件&quot;">​</a></h3><p>NVIDIA Jetson 平台继续服务边缘 AI 与机器人开发，Jetson Orin Nano Super 提供 67 TOPS AI 性能，可在本地 GPU 上运行 Mistral 等开源模型，无需云端或 API key。对机器人和现场设备来说，本地推理仍是延迟、隐私与成本的核心解法 🤖。来源：<a href="https://blogs.nvidia.com/blog/build-ai-with-nvidia-jetson" target="_blank" rel="noreferrer">NVIDIA 博客</a></p><h3 id="_5-kimi-k3-登顶竞技场全栈编码榜首" tabindex="-1">5. Kimi K3 登顶竞技场全栈编码榜首 <a class="header-anchor" href="#_5-kimi-k3-登顶竞技场全栈编码榜首" aria-label="Permalink to &quot;5. Kimi K3 登顶竞技场全栈编码榜首&quot;">​</a></h3><p>Kimi K3 在 Arena 相关编码榜单上获得高位曝光，官方社交账号与独立评测都提到它在前端/编码任务中表现突出。更准确的读法是：Kimi K3 已经具备可严肃比较的开放权重证据，但不同 harness、推理强度和任务版本仍会影响排名结论 🧠。来源：<a href="https://benchlm.ai/blog/posts/kimi-3-release-data-coming-soon" target="_blank" rel="noreferrer">BenchLM 分析</a></p><p><img src="'+m+'" alt="AI资讯：Kimi K3位列全栈编码榜第一的排行榜海报" loading="lazy"></p><h3 id="_6-马斯克强调特斯拉-fsd-显著降低事故" tabindex="-1">6. 马斯克强调特斯拉 FSD 显著降低事故 <a class="header-anchor" href="#_6-马斯克强调特斯拉-fsd-显著降低事故" aria-label="Permalink to &quot;6. 马斯克强调特斯拉 FSD 显著降低事故&quot;">​</a></h3><p>围绕 Tesla FSD Supervised 欧洲安全数据的讨论继续升温。EVwire 记录了五个欧洲国家累计 50 million km 的里程节点，并提到荷兰非高速场景从 2026-04-10 到 2026-06-05 的统计为 7.0 million km 中 3 起碰撞、高速场景 0 起碰撞；相关结论仍应结合监管审查和数据口径阅读 ⚠️。来源：<a href="https://evwire.com/p/tesla-fsd-supervised-50-million-km-europe" target="_blank" rel="noreferrer">EVwire 报道</a></p><p><img src="'+u+'" alt="AI资讯：特斯拉FSD安全数据海报展示欧洲五国行驶里程" loading="lazy"></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>AI 编程工具提速引发开发者技能退化担忧。</strong> 独立创始人在 Reddit 讨论中称，AI 编程工具把每天写代码时间压到 90 分钟，新功能周期从数天缩到数小时，但也担心调试能力退化。来源：<a href="https://www.reddit.com/r/artificial/comments/1v98szp/ai_coding_tools_are_saving_me_hours_but_i/" target="_blank" rel="noreferrer">讨论帖</a></li><li><strong>Firecrawl 在 SimpleQA 搜索评测中夺冠。</strong> 社区测试显示，Firecrawl 在 SimpleQA 搜索评测中达到 94.7% 准确率，无搜索基线为 43.8%，Claude 搜索为 90.5%。来源：<a href="https://www.reddit.com/r/artificial/comments/1v8u2vk/i_tested_firecrawl_exa_parallel_and_claude_search/" target="_blank" rel="noreferrer">测评帖</a></li><li><strong>LLM 提供商性能评估需要看延迟、吞吐量和正常运行时间。</strong> OpenRouter 提醒，同一模型在不同端点上的体验会受基础设施、量化、负载和路由策略影响。来源：<a href="https://openrouter.ai/blog/insights/evaluate-llm-provider-performance" target="_blank" rel="noreferrer">OpenRouter 博客</a></li><li><strong>AI 框架对模型表现的影响可能超过模型本身。</strong> Tom Tunguz 引用 Endor Labs 测试称，同一模型在不同 harness 上差异明显，GPT-5.5 在 Codex 框架与 Cursor 上的功能正确率分别为 61.5% 与 87.2%。来源：<a href="https://www.tomtunguz.com/aftermarket-harnesses" target="_blank" rel="noreferrer">分析文章</a></li><li><strong>LangChain 构建 Agent-First 数据栈。</strong> LangChain 用 Hex、dbt、语义模型和可观测性工具搭建可信数据智能体，将自服务分析规模提升 40 倍。来源：<a href="https://www.langchain.com/blog/agent-data-stack" target="_blank" rel="noreferrer">LangChain 博客</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>智能体入口继续下沉。</strong> Grok、Gemini Managed Agents、Perplexity Personal Computer、Google AI Mode 都在把 agent 从聊天框推向办公、搜索和桌面环境 🚀。</li><li><strong>安全问题正在前置。</strong> Claude 加密研究、Hugging Face 攻击复盘、MCP 治理工具和 AI 发展节奏讨论共同说明，能力发布必须配套审计、隔离和披露机制 🔒。</li><li><strong>长上下文进入工程优化期。</strong> Kimi K3、Kimi Linear、验证记忆和 DecoupleMix 都指向一个趋势：模型规模之外，注意力、缓存和数据配方同样决定可用性 🧠。</li><li><strong>开源工具仍是落地加速器。</strong> agent-governance-toolkit、speech-to-speech 和 book-to-skill 分别补齐治理、语音和知识迁移场景，开发者生态没有降温 🛠️。</li><li><strong>监管与商业边界更复杂。</strong> 机器人进口限制、版权裁定、Runlayer 诉 Rippling 和 Spur 融资显示，AI 基础设施竞争会越来越多地进入法律、合规与安全预算 ( •̀ ω •́ )。</li></ul>',101)])])}const w=e(b,[["render",f]]);export{x as __pageData,w as default};
